gsap:
// el = botão, a = sombra separada
const btn = el, shadow = a;
tl.fromTo(btn, { scale: 1, y: 0 }, { scale: 0.94, y: 4, duration: 0.1, ease: "none" }, t);
tl.fromTo(shadow, { opacity: 0.35, scale: 1 }, { opacity: 0.12, scale: 0.9, duration: 0.1, ease: "none" }, t);
tl.to(btn, { scale: 1, y: 0, duration: 0.5, ease: "elastic.out(1, 0.45)" }, t + 0.1);
tl.to(shadow, { opacity: 0.35, scale: 1, duration: 0.4, ease: "power2.out" }, t + 0.1);

// el = .card (transform-style: preserve-3d); frente e verso com backface-visibility: hidden
tl.fromTo(el, { rotationY: 0, transformPerspective: 1600 }, { rotationY: 180, duration: 0.7, ease: "power3.inOut" }, t);
tl.fromTo(el, { scale: 1 }, { keyframes: { scale: [1, 1.08, 1] }, duration: 0.7, ease: "none", immediateRender: false }, t);

// items = cartas de cima para baixo
const [top, ...rest] = items;
tl.fromTo(top, { x: 0, rotation: 0, opacity: 1 }, { x: 900, rotation: 18, opacity: 0, duration: 0.5, ease: "power2.in", transformOrigin: "50% 120%" }, t);
rest.forEach((c, i) => tl.fromTo(c, { y: (i + 1) * 30, scale: 1 - (i + 1) * 0.05 }, { y: i * 30, scale: 1 - i * 0.05, duration: 0.4, ease: "back.out(1.4)" }, t + 0.2));

// el = balão novo, a = indicador 'digitando', b = lista de mensagens, items = 3 pontinhos
const bubble = el, typing = a, list = b, dots = items, rowH = 140;
tl.fromTo(typing, { opacity: 0, scale: 0.8 }, { opacity: 1, scale: 1, duration: 0.2, ease: "power2.out" }, t);
tl.fromTo(dots, { y: 0 }, { y: -10, duration: 0.2, ease: "sine.inOut", yoyo: true, repeat: 3, stagger: 0.1 }, t + 0.1);
tl.fromTo(typing, { opacity: 1 }, { opacity: 0, duration: 0.1, immediateRender: false }, t + 1.0);
tl.fromTo(list, { y: 0 }, { y: -rowH, duration: 0.35, ease: "power3.out" }, t + 1.0);
tl.fromTo(bubble, { scale: 0, opacity: 0, transformOrigin: "0% 100%" }, { scale: 1, opacity: 1, duration: 0.35, ease: "back.out(1.7)" }, t + 1.0);

// el = cursor (x/y relativos ao alvo), a = botão, b = anel do clique
const cursor = el, target = a, ring = b;
tl.fromTo(cursor, { x: 380, y: 520 }, { x: 0, y: 0, duration: 0.7, ease: "power3.inOut" }, t);
tl.fromTo(cursor, { scale: 1 }, { scale: 0.85, duration: 0.08, ease: "power2.in", yoyo: true, repeat: 1, immediateRender: false }, t + 0.72);
tl.fromTo(target, { scale: 1 }, { scale: 0.96, duration: 0.08, yoyo: true, repeat: 1, immediateRender: false }, t + 0.72);
tl.fromTo(ring, { scale: 0.2, opacity: 0.6 }, { scale: 1.8, opacity: 0, duration: 0.45, ease: "power2.out" }, t + 0.74);

// el = cursor, a = item arrastado
const cursor = el, chip = a, dx = 420, dy = -300;
tl.fromTo(cursor, { scale: 1 }, { scale: 0.85, duration: 0.1, ease: "power2.out" }, t);
tl.fromTo(chip, { scale: 1, rotation: 0 }, { scale: 1.06, rotation: -3, duration: 0.15, ease: "power2.out" }, t + 0.05);
tl.fromTo([cursor, chip], { x: 0, y: 0 }, { x: dx, y: dy, duration: 0.7, ease: "power2.inOut" }, t + 0.2);
tl.to(chip, { scale: 1, rotation: 0, duration: 0.35, ease: "back.out(2)" }, t + 0.9);
tl.to(cursor, { scale: 1, duration: 0.1, ease: "power2.out" }, t + 0.9);

// el = menu, a = chevron, items = opções
const menu = el, chevron = a;
tl.fromTo(chevron, { rotation: 0 }, { rotation: 180, duration: 0.3, ease: "power2.inOut" }, t);
tl.fromTo(menu, { clipPath: "inset(0% 0% 100% 0% round 24px)", opacity: 0.5 }, { clipPath: "inset(0% 0% 0% 0% round 24px)", opacity: 1, duration: 0.35, ease: "power3.out" }, t);
tl.fromTo(items, { opacity: 0, y: -10 }, { opacity: 1, y: 0, duration: 0.25, ease: "power2.out", stagger: 0.04 }, t + 0.1);

// el = caret, a = placeholder, b = span do texto (data-text); .focus-ring no campo
const ring = scene.querySelector(".focus-ring"), caret = el, ph = a, txt = b;
const full = txt.dataset.text, p = { n: 0 }, speed = 0.05;
tl.fromTo(ring, { opacity: 0, scale: 1.04 }, { opacity: 1, scale: 1, duration: 0.2, ease: "power2.out" }, t);
tl.fromTo(ph, { opacity: 0.5 }, { opacity: 0, duration: 0.1 }, t + 0.25);
tl.fromTo(p, { n: 0 }, { n: full.length, duration: full.length * speed, ease: "none", onUpdate: () => { txt.textContent = full.slice(0, Math.round(p.n)); } }, t + 0.25);
// caret pisca só depois de terminar (finito)
const end = t + 0.25 + full.length * speed;
for (let k = 0; k < 6; k++) tl.set(caret, { opacity: k % 2 ? 1 : 0 }, end + k * 0.4);

// el = coração cheio (sobre o vazio), a = anel <circle>, items = 6 pontinhos
const heart = el, ring = a, dots = items;
tl.fromTo(heart, { scale: 0 }, { keyframes: { scale: [0, 1.3, 0.9, 1] }, duration: 0.5, ease: "none" }, t + 0.08);
tl.fromTo(ring, { scale: 0.2, opacity: 1, strokeWidth: 30 }, { scale: 1.4, opacity: 0, strokeWidth: 0, duration: 0.4, ease: "power2.out" }, t);
dots.forEach((d, i) => {
  const ang = (i / dots.length) * Math.PI * 2;
  tl.fromTo(d, { x: 0, y: 0, scale: 1, opacity: 1 }, { x: Math.cos(ang) * 120, y: Math.sin(ang) * 120, scale: 0, opacity: 0, duration: 0.5, ease: "power2.out" }, t + 0.1);
});

// el = modal, a = backdrop; .app = conteúdo por trás
tl.fromTo(a, { opacity: 0 }, { opacity: 0.55, duration: 0.25, ease: "power1.out" }, t);
tl.fromTo(scene.querySelector(".app"), { filter: "blur(0px)" }, { filter: "blur(6px)", duration: 0.3, ease: "power1.out" }, t);
tl.fromTo(el, { scale: 0.88, y: 40, opacity: 0 }, { scale: 1, y: 0, opacity: 1, duration: 0.4, ease: "back.out(1.4)" }, t + 0.05);

// el = banner, items = [ícone, título, texto]
tl.fromTo(el, { y: -220, opacity: 0, scale: 0.96 }, { y: 0, opacity: 1, scale: 1, duration: 0.5, ease: "back.out(1.2)" }, t);
tl.fromTo(items, { opacity: 0, y: -6 }, { opacity: 1, y: 0, duration: 0.25, ease: "power2.out", stagger: 0.06 }, t + 0.2);
tl.to(el, { y: -220, opacity: 0, duration: 0.35, ease: "power3.in" }, t + 2.5);

// el = mockup do celular, a = tela do app
const phone = el, screen = a;
tl.fromTo(phone, { y: 900, rotationX: 35, rotation: -8, transformPerspective: 2000 }, { y: 0, rotationX: 0, rotation: 0, duration: 0.9, ease: "power3.out" }, t);
tl.fromTo(screen, { filter: "brightness(0)" }, { filter: "brightness(1)", duration: 0.4, ease: "power2.out" }, t + 0.7);

// .step .done = camada preenchida de cada círculo; .step-line .fill = conector
const dots = scene.querySelectorAll(".step .done"), lines = scene.querySelectorAll(".step-line .fill"), step = 0.6;
tl.fromTo(dots, { scale: 0, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.25, ease: "back.out(2)", stagger: step }, t);
tl.fromTo(lines, { scaleX: 0, transformOrigin: "0% 50%" }, { scaleX: 1, duration: step - 0.25, ease: "power2.inOut", stagger: step }, t + 0.25);

// el = conteúdo longo dentro da tela do mockup (overflow: hidden)
const stops = [0, -700, -1500, -2300];
stops.slice(1).forEach((y, k) => tl.fromTo(el, { y: stops[k] }, { y, duration: 0.6, ease: "power3.out", immediateRender: k === 0 }, t + k * 1.0));

// el = faixa de brilho (mascarada pelos blocos), a = conteúdo real, b = blocos do esqueleto
const shine = el, real = a, skel = b, sweep = 0.9, n = 2;
tl.fromTo(shine, { xPercent: -100 }, { xPercent: 100, duration: sweep, ease: "power1.inOut", repeat: n - 1 }, t);
tl.fromTo(skel, { opacity: 1 }, { opacity: 0, duration: 0.25, ease: "power1.out" }, t + sweep * n);
tl.fromTo(real, { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.35, ease: "power2.out" }, t + sweep * n);

// el = bolinha, a = preenchimento da trilha, b = número exibido
const knob = el, fill = a, readout = b, W = 700, from = 0.2, to = 0.85, c = { v: from };
tl.fromTo(knob, { x: W * from }, { x: W * to, duration: 1.0, ease: "power2.inOut" }, t);
tl.fromTo(fill, { scaleX: from, transformOrigin: "0% 50%" }, { scaleX: to, duration: 1.0, ease: "power2.inOut" }, t);
tl.fromTo(c, { v: from }, { v: to, duration: 1.0, ease: "power2.inOut", onUpdate: () => (readout.textContent = Math.round(c.v * 100)) }, t);

// el = indicador, a = painel antigo, b = painel novo
const pill = el, oldP = a, newP = b, dx = 360;
tl.fromTo(pill, { x: 0 }, { x: dx, duration: 0.4, ease: "power3.inOut" }, t);
tl.fromTo(pill, { scaleX: 1 }, { keyframes: { scaleX: [1, 1.4, 1] }, duration: 0.4, ease: "none", immediateRender: false }, t);
tl.fromTo(oldP, { x: 0, opacity: 1 }, { x: -80, opacity: 0, duration: 0.3, ease: "power2.in" }, t);
tl.fromTo(newP, { x: 80, opacity: 0 }, { x: 0, opacity: 1, duration: 0.35, ease: "power2.out" }, t + 0.2);

// el = ripple dentro do botão (overflow: hidden), a = marca do dedo
tl.fromTo(el, { scale: 0, opacity: 0.35 }, { scale: 1, duration: 0.35, ease: "power2.out" }, t);
tl.fromTo(el, { opacity: 0.35 }, { opacity: 0, duration: 0.3, ease: "power1.out", immediateRender: false }, t + 0.35);
tl.fromTo(a, { scale: 0.6, opacity: 0 }, { scale: 1, opacity: 0.5, duration: 0.12, ease: "power2.out" }, t);
tl.fromTo(a, { scale: 1, opacity: 0.5 }, { scale: 1.3, opacity: 0, duration: 0.3, ease: "power2.out", immediateRender: false }, t + 0.2);

// el = pílula do toast, a = ícone
tl.fromTo(el, { y: 120, opacity: 0, scale: 0.9 }, { y: 0, opacity: 1, scale: 1, duration: 0.35, ease: "back.out(1.6)" }, t);
tl.fromTo(a, { scale: 0, rotation: -30 }, { scale: 1, rotation: 0, duration: 0.3, ease: "back.out(2.5)" }, t + 0.15);
tl.to(el, { y: 40, opacity: 0, duration: 0.3, ease: "power2.in" }, t + 0.35 + 1.6);

// el = bolinha, a = camada 'ligado' do trilho
const knob = el, onLayer = a, travel = 64;
tl.fromTo(knob, { x: 0 }, { x: travel, duration: 0.3, ease: "back.out(1.6)" }, t);
tl.fromTo(knob, { scaleX: 1 }, { keyframes: { scaleX: [1, 1.25, 1] }, duration: 0.3, ease: "none", transformOrigin: "50% 50%", immediateRender: false }, t);
tl.fromTo(onLayer, { opacity: 0 }, { opacity: 1, duration: 0.25, ease: "power2.out" }, t);
